        function drawVisualiser(bufferLength, barWidth, x, dataArray ){
            for( let i=0; i<dataArray.length; i++){
                let barHeight = dataArray[i]*1.5; // Assign the value here
                context.save();
                context.translate(canvas.width/2, canvas.height/2);
                context.rotate(i * Math.PI*4/bufferLength);
                const hue = (i/bufferLength)*360
                context.fillStyle = "hsl(" + hue + ", 80%, 60%)";
                context.fillRect(0, 0, barWidth, barHeight);
                x += barWidth;
                context.restore();
            }
