Here is an example:
#include <vector>
#include <iostream>
class parent{
public:
  virtual ~parent(){};
  auto & operator()(const int i);
};
template<typename T>
class child:public parent{
protected:
  std::vector<T> X_;
public:
  child(std::vector<T> const &X):X_{X}{};
  T & operator()(const int i){
    return(X_[i]);
  }
};
auto & parent::operator()(const int i){
  if(auto * x=dynamic_cast<child<int>*>(this)){
    return((*x)(i));
  }else if(auto * x=dynamic_cast<child<double>*>(this)){
    return((*x)(i));
  }else{
    throw std::string("error");
  }
};
int main(){
  child Y1(std::vector<int>{5,10});
  child Y2(std::vector<double>{6,11});
  std::cout<<Y1(0)<<std::endl;
  parent * X=&Y1;
  std::cout<<(*X)(0)<<std::endl;
}

Currently I get: error: 'auto' in return type deduced as 'double' here but deduced as 'int' in earlier return statement
Any suggestions much appreciated.
A practical example arises when building a vector of parent pointers to child vectors:
int main(){
  std::vector<std::shared_ptr<parent>> Z;
  Z.push_back(std::make_shared<child<int>>(std::vector<int>{5,10}));
  Z.push_back(std::make_shared<child<double>>(std::vector<double>{5,10}));
  std::cout<<(*Z[0])(1)<<std::endl;
}

A working solution to access elements of the child vector would be to drop the operator in the parent class and to resolve the pointer in a loop:
#include <vector>
#include <iostream>
#include <memory>
class parent{
public:
  virtual ~parent(){};
};
template<typename T>
class child:public parent{
protected:
  std::vector<T> X_;
public:
  child(std::vector<T> const &X):X_{X}{};
  T & operator()(const int i){
    return(X_[i]);
  }
};
int main(){
  std::vector<std::shared_ptr<parent>> Z;
  Z.push_back(std::make_shared<child<int>>(std::vector<int>{5,10}));
  Z.push_back(std::make_shared<child<double>>(std::vector<double>{5,10}));
  for(auto &x:Z){
    if(auto xx=std::dynamic_pointer_cast<child<int>>(x)){
      std::cout<<(*xx)(0)<<std::endl;
    }else if(auto xx=std::dynamic_pointer_cast<child<double>>(x)){
      std::cout<<(*xx)(0)<<std::endl;
    }
  }
}

But this would mean that throughout the code every loop iterating over Z must be reworked if a child is is being invoked with a previously unused template parameter (i.e. adding Z.push_back(std::make_shared<child<float>>(std::vector<float>{5,10})); to the code would require to manually extend the if branches in the subsequent loop).
The goal is to avoid this manual extension of the loop.

